// -----------------------------------------------------------------------------
// prim_CRC_Calculator_tb
// -----------------------------------------------------------------------------
// Self-checking testbench for prim_CRC_Calculator.
//
// Expected values come from crc_expected.svh, generated by crc_ref.py, an
// INDEPENDENT bit-serial reference model that is itself validated against
// the published check values of the CRC catalogue (reveng). The D=8 checks
// below therefore anchor the RTL to external ground truth:
//
//   CRC-32 ("123456789")           -> 32'hCBF43926
//   CRC-16/MODBUS                  -> 16'h4B37
//   CRC-16/CCITT-FALSE             -> 16'h29B1
//   CRC-16/XMODEM                  -> 16'h31C3
//   CRC-8/SMBUS                    -> 8'hF4
//   CRC-8/ROHC                     -> 8'hD0
//   CRC-32/MPEG-2                  -> 32'h0376E6E7
//   CRC-16/ARC                     -> 16'hBB3D
//
// Coverage:
//   - CRC_WIDTH = 6 / 8 / 16 / 32, DATA_WIDTH = 1 / 3 / 4 / 6 / 8 / 12 / 16 / 24 / 32
//   - DATA_WIDTH smaller, equal and larger than CRC_WIDTH
//   - tail-chunk path (DATA_WIDTH not a multiple of CHUNK_W)
//   - REFIN / REFOUT / LSB_FIRST combinations, BE and LE beat packing
//   - running (mid-stream) and final values, hold across idle cycles
//   - reset value of CRC_o for every configuration
//
// Run:  verilator --binary --timing +incdir+. prim_CRC_Calculator_tb.sv \
//                  prim_CRC_Calculator.sv --top-module prim_CRC_Calculator_tb
// -----------------------------------------------------------------------------

`timescale 1ns/1ps

module tb_prim_CRC_Calculator;

  `include "crc_expected.svh"

  // -------------------------------------------------------------------------
  // Clock / reset
  // -------------------------------------------------------------------------
  logic clk;
  logic rst;
  integer errors = 0;
  integer checks = 0;

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  // -------------------------------------------------------------------------
  // DATA_WIDTH = 8 shared bus (9 configurations)
  // -------------------------------------------------------------------------
  logic        dv8;
  logic [7:0]  dat8;

  // CRC-32 (Ethernet): catalog anchor
  prim_CRC_Calculator #(
    .CRC_WIDTH(32), .DATA_WIDTH(8),
    .CRC_POLY(32'h04C11DB7), .CRC_INIT(32'hFFFFFFFF), .CRC_XOR_OUT(32'hFFFFFFFF),
    .REFIN(1'b1), .REFOUT(1'b1), .LSB_FIRST(1'b0)
  ) dut_crc32_d8 (
    .CLK_i(clk), .RST_i(rst),
    .DataValid_i(dv8), .Data_i(dat8), .CRC_o(crc32_d8)
  );
  logic [31:0] crc32_d8;

  // CRC-16/MODBUS: catalog anchor
  prim_CRC_Calculator #(
    .CRC_WIDTH(16), .DATA_WIDTH(8),
    .CRC_POLY(16'h8005), .CRC_INIT(16'hFFFF), .CRC_XOR_OUT(16'h0000),
    .REFIN(1'b1), .REFOUT(1'b1), .LSB_FIRST(1'b0)
  ) dut_modbus_d8 (
    .CLK_i(clk), .RST_i(rst),
    .DataValid_i(dv8), .Data_i(dat8), .CRC_o(modbus_d8)
  );
  logic [15:0] modbus_d8;

  // CRC-16/CCITT-FALSE: catalog anchor
  prim_CRC_Calculator #(
    .CRC_WIDTH(16), .DATA_WIDTH(8),
    .CRC_POLY(16'h1021), .CRC_INIT(16'hFFFF), .CRC_XOR_OUT(16'h0000),
    .REFIN(1'b0), .REFOUT(1'b0), .LSB_FIRST(1'b0)
  ) dut_ccittf_d8 (
    .CLK_i(clk), .RST_i(rst),
    .DataValid_i(dv8), .Data_i(dat8), .CRC_o(ccittf_d8)
  );
  logic [15:0] ccittf_d8;

  // CRC-16/XMODEM: catalog anchor
  prim_CRC_Calculator #(
    .CRC_WIDTH(16), .DATA_WIDTH(8),
    .CRC_POLY(16'h1021), .CRC_INIT(16'h0000), .CRC_XOR_OUT(16'h0000),
    .REFIN(1'b0), .REFOUT(1'b0), .LSB_FIRST(1'b0)
  ) dut_xmodem_d8 (
    .CLK_i(clk), .RST_i(rst),
    .DataValid_i(dv8), .Data_i(dat8), .CRC_o(xmodem_d8)
  );
  logic [15:0] xmodem_d8;

  // CRC-8/SMBUS: catalog anchor
  prim_CRC_Calculator #(
    .CRC_WIDTH(8), .DATA_WIDTH(8),
    .CRC_POLY(8'h07), .CRC_INIT(8'h00), .CRC_XOR_OUT(8'h00),
    .REFIN(1'b0), .REFOUT(1'b0), .LSB_FIRST(1'b0)
  ) dut_smbus_d8 (
    .CLK_i(clk), .RST_i(rst),
    .DataValid_i(dv8), .Data_i(dat8), .CRC_o(smbus_d8)
  );
  logic [7:0] smbus_d8;

  // CRC-8/ROHC: catalog anchor
  prim_CRC_Calculator #(
    .CRC_WIDTH(8), .DATA_WIDTH(8),
    .CRC_POLY(8'h07), .CRC_INIT(8'hFF), .CRC_XOR_OUT(8'h00),
    .REFIN(1'b1), .REFOUT(1'b1), .LSB_FIRST(1'b0)
  ) dut_rohc_d8 (
    .CLK_i(clk), .RST_i(rst),
    .DataValid_i(dv8), .Data_i(dat8), .CRC_o(rohc_d8)
  );
  logic [7:0] rohc_d8;

  // CRC-32/MPEG-2: catalog anchor
  prim_CRC_Calculator #(
    .CRC_WIDTH(32), .DATA_WIDTH(8),
    .CRC_POLY(32'h04C11DB7), .CRC_INIT(32'hFFFFFFFF), .CRC_XOR_OUT(32'h00000000),
    .REFIN(1'b0), .REFOUT(1'b0), .LSB_FIRST(1'b0)
  ) dut_mpeg2_d8 (
    .CLK_i(clk), .RST_i(rst),
    .DataValid_i(dv8), .Data_i(dat8), .CRC_o(mpeg2_d8)
  );
  logic [31:0] mpeg2_d8;

  // CRC-16/ARC: catalog anchor
  prim_CRC_Calculator #(
    .CRC_WIDTH(16), .DATA_WIDTH(8),
    .CRC_POLY(16'h8005), .CRC_INIT(16'h0000), .CRC_XOR_OUT(16'h0000),
    .REFIN(1'b1), .REFOUT(1'b1), .LSB_FIRST(1'b0)
  ) dut_arc_d8 (
    .CLK_i(clk), .RST_i(rst),
    .DataValid_i(dv8), .Data_i(dat8), .CRC_o(arc_d8)
  );
  logic [15:0] arc_d8;

  // Module defaults (CRC_WIDTH=6): user parameterization
  prim_CRC_Calculator #(
    .CRC_WIDTH(6), .DATA_WIDTH(8),
    .CRC_POLY(6'h2F), .CRC_INIT(6'h2A), .CRC_XOR_OUT(6'h15),
    .REFIN(1'b1), .REFOUT(1'b1), .LSB_FIRST(1'b0)
  ) dut_user6_d8 (
    .CLK_i(clk), .RST_i(rst),
    .DataValid_i(dv8), .Data_i(dat8), .CRC_o(user6_d8)
  );
  logic [5:0] user6_d8;

  // -------------------------------------------------------------------------
  // Wide-beat instances
  // -------------------------------------------------------------------------
  logic        dv32;   logic [31:0] dat32;    // BE packing, LSB_FIRST=0
  logic        dv32le; logic [31:0] dat32le;  // LE packing, LSB_FIRST=1
  logic        dv12;   logic [11:0] dat12;    // tail-chunk path
  logic        dv16le; logic [15:0] dat16le;
  logic        dv16;   logic [15:0] dat16;
  logic        dv24;   logic [23:0] dat24;
  logic        dv6;    logic [5:0]  dat6;
  logic        dv4;    logic [3:0]  dat4;
  logic        dv3;    logic [2:0]  dat3;
  logic        dv3u;   logic [2:0]  dat3u;    // module defaults, 3-bit beats
  logic        dv1a;   logic        dat1a;    // CRC-32, REFIN=0, pre-reflected stream
  logic        dv1b;   logic        dat1b;    // CRC-32, REFIN=1, raw stream

  // CRC-32 and CRC-32/MPEG-2, DATA_WIDTH = 32, big-endian beats
  prim_CRC_Calculator #(
    .CRC_WIDTH(32), .DATA_WIDTH(32),
    .CRC_POLY(32'h04C11DB7), .CRC_INIT(32'hFFFFFFFF), .CRC_XOR_OUT(32'hFFFFFFFF),
    .REFIN(1'b1), .REFOUT(1'b1), .LSB_FIRST(1'b0)
  ) dut_crc32_d32_be (
    .CLK_i(clk), .RST_i(rst),
    .DataValid_i(dv32), .Data_i(dat32), .CRC_o(crc32_d32_be)
  );
  logic [31:0] crc32_d32_be;

  prim_CRC_Calculator #(
    .CRC_WIDTH(32), .DATA_WIDTH(32),
    .CRC_POLY(32'h04C11DB7), .CRC_INIT(32'hFFFFFFFF), .CRC_XOR_OUT(32'h00000000),
    .REFIN(1'b0), .REFOUT(1'b0), .LSB_FIRST(1'b0)
  ) dut_mpeg2_d32_be (
    .CLK_i(clk), .RST_i(rst),
    .DataValid_i(dv32), .Data_i(dat32), .CRC_o(mpeg2_d32_be)
  );
  logic [31:0] mpeg2_d32_be;

  // CRC-32, DATA_WIDTH = 32, little-endian beat packing
  prim_CRC_Calculator #(
    .CRC_WIDTH(32), .DATA_WIDTH(32),
    .CRC_POLY(32'h04C11DB7), .CRC_INIT(32'hFFFFFFFF), .CRC_XOR_OUT(32'hFFFFFFFF),
    .REFIN(1'b1), .REFOUT(1'b1), .LSB_FIRST(1'b1)
  ) dut_crc32_d32_le (
    .CLK_i(clk), .RST_i(rst),
    .DataValid_i(dv32le), .Data_i(dat32le), .CRC_o(crc32_d32_le)
  );
  logic [31:0] crc32_d32_le;

  // CRC-32/MPEG-2, DATA_WIDTH = 12: one full chunk + 4-bit tail
  prim_CRC_Calculator #(
    .CRC_WIDTH(32), .DATA_WIDTH(12),
    .CRC_POLY(32'h04C11DB7), .CRC_INIT(32'hFFFFFFFF), .CRC_XOR_OUT(32'h00000000),
    .REFIN(1'b0), .REFOUT(1'b0), .LSB_FIRST(1'b0)
  ) dut_mpeg2_d12_be (
    .CLK_i(clk), .RST_i(rst),
    .DataValid_i(dv12), .Data_i(dat12), .CRC_o(mpeg2_d12_be)
  );
  logic [31:0] mpeg2_d12_be;

  // CRC-16/MODBUS, DATA_WIDTH = 16, little-endian beat packing
  prim_CRC_Calculator #(
    .CRC_WIDTH(16), .DATA_WIDTH(16),
    .CRC_POLY(16'h8005), .CRC_INIT(16'hFFFF), .CRC_XOR_OUT(16'h0000),
    .REFIN(1'b1), .REFOUT(1'b1), .LSB_FIRST(1'b1)
  ) dut_modbus_d16_le (
    .CLK_i(clk), .RST_i(rst),
    .DataValid_i(dv16le), .Data_i(dat16le), .CRC_o(modbus_d16_le)
  );
  logic [15:0] modbus_d16_le;

  // CRC-16/XMODEM, DATA_WIDTH = 24
  prim_CRC_Calculator #(
    .CRC_WIDTH(16), .DATA_WIDTH(24),
    .CRC_POLY(16'h1021), .CRC_INIT(16'h0000), .CRC_XOR_OUT(16'h0000),
    .REFIN(1'b0), .REFOUT(1'b0), .LSB_FIRST(1'b0)
  ) dut_xmodem_d24_be (
    .CLK_i(clk), .RST_i(rst),
    .DataValid_i(dv24), .Data_i(dat24), .CRC_o(xmodem_d24_be)
  );
  logic [15:0] xmodem_d24_be;

  // Module defaults, DATA_WIDTH = 16: tail path with REFIN
  prim_CRC_Calculator #(
    .CRC_WIDTH(6), .DATA_WIDTH(16),
    .CRC_POLY(6'h2F), .CRC_INIT(6'h2A), .CRC_XOR_OUT(6'h15),
    .REFIN(1'b1), .REFOUT(1'b1), .LSB_FIRST(1'b0)
  ) dut_user6_d16_be (
    .CLK_i(clk), .RST_i(rst),
    .DataValid_i(dv16), .Data_i(dat16), .CRC_o(user6_d16_be)
  );
  logic [5:0] user6_d16_be;

  // Module defaults, DATA_WIDTH = 6: single wide chunk (table = 64 entries)
  prim_CRC_Calculator #(
    .CRC_WIDTH(6), .DATA_WIDTH(6),
    .CRC_POLY(6'h2F), .CRC_INIT(6'h2A), .CRC_XOR_OUT(6'h15),
    .REFIN(1'b1), .REFOUT(1'b1), .LSB_FIRST(1'b0)
  ) dut_user6_d6_be (
    .CLK_i(clk), .RST_i(rst),
    .DataValid_i(dv6), .Data_i(dat6), .CRC_o(user6_d6_be)
  );
  logic [5:0] user6_d6_be;

  // CRC-16/CCITT-FALSE, DATA_WIDTH = 4 (nibble beats, sub-byte REFIN)
  prim_CRC_Calculator #(
    .CRC_WIDTH(16), .DATA_WIDTH(4),
    .CRC_POLY(16'h1021), .CRC_INIT(16'hFFFF), .CRC_XOR_OUT(16'h0000),
    .REFIN(1'b0), .REFOUT(1'b0), .LSB_FIRST(1'b0)
  ) dut_ccittf_d4_be (
    .CLK_i(clk), .RST_i(rst),
    .DataValid_i(dv4), .Data_i(dat4), .CRC_o(ccittf_d4_be)
  );
  logic [15:0] ccittf_d4_be;

  // CRC-8/SMBUS, DATA_WIDTH = 3 (tail path on 8-bit CRC)
  prim_CRC_Calculator #(
    .CRC_WIDTH(8), .DATA_WIDTH(3),
    .CRC_POLY(8'h07), .CRC_INIT(8'h00), .CRC_XOR_OUT(8'h00),
    .REFIN(1'b0), .REFOUT(1'b0), .LSB_FIRST(1'b0)
  ) dut_smbus_d3_be (
    .CLK_i(clk), .RST_i(rst),
    .DataValid_i(dv3), .Data_i(dat3), .CRC_o(smbus_d3_be)
  );
  logic [7:0] smbus_d3_be;

  // Module defaults, DATA_WIDTH = 3: sub-byte REFIN (3-bit lane)
  prim_CRC_Calculator #(
    .CRC_WIDTH(6), .DATA_WIDTH(3),
    .CRC_POLY(6'h2F), .CRC_INIT(6'h2A), .CRC_XOR_OUT(6'h15),
    .REFIN(1'b1), .REFOUT(1'b1), .LSB_FIRST(1'b0)
  ) dut_user6_d3_be (
    .CLK_i(clk), .RST_i(rst),
    .DataValid_i(dv3u), .Data_i(dat3u), .CRC_o(user6_d3_be)
  );
  logic [5:0] user6_d3_be;

  // CRC-32, DATA_WIDTH = 1 (bit-serial, REFIN=0, pre-reflected stream)
  prim_CRC_Calculator #(
    .CRC_WIDTH(32), .DATA_WIDTH(1),
    .CRC_POLY(32'h04C11DB7), .CRC_INIT(32'hFFFFFFFF), .CRC_XOR_OUT(32'hFFFFFFFF),
    .REFIN(1'b0), .REFOUT(1'b1), .LSB_FIRST(1'b0)
  ) dut_crc32_d1_ref0 (
    .CLK_i(clk), .RST_i(rst),
    .DataValid_i(dv1a), .Data_i(dat1a), .CRC_o(crc32_d1_ref0)
  );
  logic [31:0] crc32_d1_ref0;

  // CRC-32, DATA_WIDTH = 1 (bit-serial, REFIN=1, raw stream)
  prim_CRC_Calculator #(
    .CRC_WIDTH(32), .DATA_WIDTH(1),
    .CRC_POLY(32'h04C11DB7), .CRC_INIT(32'hFFFFFFFF), .CRC_XOR_OUT(32'hFFFFFFFF),
    .REFIN(1'b1), .REFOUT(1'b1), .LSB_FIRST(1'b0)
  ) dut_crc32_d1_ref1 (
    .CLK_i(clk), .RST_i(rst),
    .DataValid_i(dv1b), .Data_i(dat1b), .CRC_o(crc32_d1_ref1)
  );
  logic [31:0] crc32_d1_ref1;

  // -------------------------------------------------------------------------
  // Driving / checking helpers
  // -------------------------------------------------------------------------
  task automatic do_reset();
    begin
      rst  = 1'b1;
      dv8  = 1'b0; dat8  = '0;
      dv32 = 1'b0; dat32 = '0;
      dv32le = 1'b0; dat32le = '0;
      dv12 = 1'b0; dat12 = '0;
      dv16le = 1'b0; dat16le = '0;
      dv16 = 1'b0; dat16 = '0;
      dv24 = 1'b0; dat24 = '0;
      dv6  = 1'b0; dat6  = '0;
      dv4  = 1'b0; dat4  = '0;
      dv3  = 1'b0; dat3  = '0;
      dv3u = 1'b0; dat3u = '0;
      dv1a = 1'b0; dat1a = 1'b0;
      dv1b = 1'b0; dat1b = 1'b0;
      repeat (3) @(negedge clk);
      rst = 1'b0;
      @(negedge clk);
    end
  endtask

  task automatic send8(input logic [7:0] b);
    begin
      @(negedge clk); dv8 = 1'b1; dat8 = b;
      @(negedge clk); dv8 = 1'b0;
    end
  endtask

  task automatic send32(input logic [31:0] b);
    begin
      @(negedge clk); dv32 = 1'b1; dat32 = b;
      @(negedge clk); dv32 = 1'b0;
    end
  endtask

  task automatic send32le(input logic [31:0] b);
    begin
      @(negedge clk); dv32le = 1'b1; dat32le = b;
      @(negedge clk); dv32le = 1'b0;
    end
  endtask

  task automatic send12(input logic [11:0] b);
    begin
      @(negedge clk); dv12 = 1'b1; dat12 = b;
      @(negedge clk); dv12 = 1'b0;
    end
  endtask

  task automatic send16le(input logic [15:0] b);
    begin
      @(negedge clk); dv16le = 1'b1; dat16le = b;
      @(negedge clk); dv16le = 1'b0;
    end
  endtask

  task automatic send16(input logic [15:0] b);
    begin
      @(negedge clk); dv16 = 1'b1; dat16 = b;
      @(negedge clk); dv16 = 1'b0;
    end
  endtask

  task automatic send24(input logic [23:0] b);
    begin
      @(negedge clk); dv24 = 1'b1; dat24 = b;
      @(negedge clk); dv24 = 1'b0;
    end
  endtask

  task automatic send6(input logic [5:0] b);
    begin
      @(negedge clk); dv6 = 1'b1; dat6 = b;
      @(negedge clk); dv6 = 1'b0;
    end
  endtask

  task automatic send4(input logic [3:0] b);
    begin
      @(negedge clk); dv4 = 1'b1; dat4 = b;
      @(negedge clk); dv4 = 1'b0;
    end
  endtask

  task automatic send3(input logic [2:0] b);
    begin
      @(negedge clk); dv3 = 1'b1; dat3 = b;
      @(negedge clk); dv3 = 1'b0;
    end
  endtask

  task automatic send3u(input logic [2:0] b);
    begin
      @(negedge clk); dv3u = 1'b1; dat3u = b;
      @(negedge clk); dv3u = 1'b0;
    end
  endtask

  task automatic send1a(input logic b);
    begin
      @(negedge clk); dv1a = 1'b1; dat1a = b;
      @(negedge clk); dv1a = 1'b0;
    end
  endtask

  task automatic send1b(input logic b);
    begin
      @(negedge clk); dv1b = 1'b1; dat1b = b;
      @(negedge clk); dv1b = 1'b0;
    end
  endtask

  task automatic idle8();
    begin
      @(negedge clk);
    end
  endtask

  task automatic check(string nm, logic [63:0] got, logic [63:0] exp,
                       int unsigned w);
    logic [63:0] m;
    begin
      m    = (w >= 64) ? '1 : ((64'h1 << w) - 1);
      checks = checks + 1;
      if ((got & m) != (exp & m)) begin
        $display("[FAIL] %-28s got=0x%0h exp=0x%0h", nm, got & m, exp & m);
        errors = errors + 1;
      end else begin
        $display("[PASS] %-28s = 0x%0h", nm, got & m);
      end
    end
  endtask

  // -------------------------------------------------------------------------
  // Stimulus
  // -------------------------------------------------------------------------
  initial begin
    // ---- reset values of every instance -----------------------------------
    do_reset();
    check("RST crc32_d8",      crc32_d8,      RST_CRC32,  32);
    check("RST modbus_d8",     modbus_d8,     RST_MODBUS, 16);
    check("RST ccittf_d8",     ccittf_d8,     RST_CCITTF, 16);
    check("RST xmodem_d8",     xmodem_d8,     RST_XMODEM, 16);
    check("RST smbus_d8",      smbus_d8,      RST_SMBUS,   8);
    check("RST rohc_d8",       rohc_d8,       RST_ROHC,    8);
    check("RST mpeg2_d8",      mpeg2_d8,      RST_MPEG2,  32);
    check("RST arc_d8",        arc_d8,        RST_ARC,    16);
    check("RST user6_d8",      user6_d8,      RST_USER6,   6);
    check("RST crc32_d32_be",  crc32_d32_be,  RST_CRC32_D32_BE,  32);
    check("RST mpeg2_d32_be",  mpeg2_d32_be,  RST_MPEG2_D32_BE,  32);
    check("RST crc32_d32_le",  crc32_d32_le,  RST_CRC32_D32_LE,  32);
    check("RST mpeg2_d12_be",  mpeg2_d12_be,  RST_MPEG2_D12_BE,  32);
    check("RST modbus_d16_le", modbus_d16_le, RST_MODBUS_D16_LE, 16);
    check("RST xmodem_d24_be", xmodem_d24_be, RST_XMODEM_D24_BE, 16);
    check("RST user6_d16_be",  user6_d16_be,  RST_USER6_D16_BE,   6);
    check("RST user6_d6_be",   user6_d6_be,   RST_USER6_D6_BE,    6);
    check("RST ccittf_d4_be",  ccittf_d4_be,  RST_CCITTF_D4_BE,  16);
    check("RST smbus_d3_be",   smbus_d3_be,   RST_SMBUS_D3_BE,    8);
    check("RST user6_d3_be",   user6_d3_be,   RST_USER6_D3_BE,    6);
    check("RST crc32_d1_ref0", crc32_d1_ref0, RST_CRC32_D1_REF0, 32);
    check("RST crc32_d1_ref1", crc32_d1_ref1, RST_CRC32_D1_REF1, 32);

    // ---- phase 1: msg9 on the D=8 bus (catalog check values) ---------------
    for (int i = 0; i < 4; i++) send8(MSG9[i]);
    idle8(); idle8();                       // hold across idle cycles
    check("RUN crc32_d8  (4B)",  crc32_d8,  EXP_P1_CRC32_A4,  32);
    check("RUN modbus_d8 (4B)",  modbus_d8, EXP_P1_MODBUS_A4, 16);
    check("RUN ccittf_d8 (4B)",  ccittf_d8, EXP_P1_CCITTF_A4, 16);
    check("RUN xmodem_d8 (4B)",  xmodem_d8, EXP_P1_XMODEM_A4, 16);
    check("RUN smbus_d8  (4B)",  smbus_d8,  EXP_P1_SMBUS_A4,   8);
    check("RUN rohc_d8   (4B)",  rohc_d8,   EXP_P1_ROHC_A4,    8);
    check("RUN mpeg2_d8  (4B)",  mpeg2_d8,  EXP_P1_MPEG2_A4,  32);
    check("RUN arc_d8    (4B)",  arc_d8,    EXP_P1_ARC_A4,    16);
    check("RUN user6_d8  (4B)",  user6_d8,  EXP_P1_USER6_A4,   6);
    for (int i = 4; i < N_MSG9; i++) send8(MSG9[i]);
    #1;
    check("FIN crc32_d8  msg9",  crc32_d8,  EXP_P1_CRC32,  32);
    check("FIN modbus_d8 msg9",  modbus_d8, EXP_P1_MODBUS, 16);
    check("FIN ccittf_d8 msg9",  ccittf_d8, EXP_P1_CCITTF, 16);
    check("FIN xmodem_d8 msg9",  xmodem_d8, EXP_P1_XMODEM, 16);
    check("FIN smbus_d8  msg9",  smbus_d8,  EXP_P1_SMBUS,   8);
    check("FIN rohc_d8   msg9",  rohc_d8,   EXP_P1_ROHC,    8);
    check("FIN mpeg2_d8  msg9",  mpeg2_d8,  EXP_P1_MPEG2,  32);
    check("FIN arc_d8    msg9",  arc_d8,    EXP_P1_ARC,    16);
    check("FIN user6_d8  msg9",  user6_d8,  EXP_P1_USER6,   6);

    // ---- phase 2: msg12 on the D=8 bus (cross-D baseline) ------------------
    do_reset();
    for (int i = 0; i < N_MSG12; i++) send8(MSG12[i]);
    #1;
    check("FIN crc32_d8  msg12",  crc32_d8,  EXP_P2_CRC32,  32);
    check("FIN modbus_d8 msg12",  modbus_d8, EXP_P2_MODBUS, 16);
    check("FIN ccittf_d8 msg12",  ccittf_d8, EXP_P2_CCITTF, 16);
    check("FIN xmodem_d8 msg12",  xmodem_d8, EXP_P2_XMODEM, 16);
    check("FIN smbus_d8  msg12",  smbus_d8,  EXP_P2_SMBUS,   8);
    check("FIN rohc_d8   msg12",  rohc_d8,   EXP_P2_ROHC,    8);
    check("FIN mpeg2_d8  msg12",  mpeg2_d8,  EXP_P2_MPEG2,  32);
    check("FIN arc_d8    msg12",  arc_d8,    EXP_P2_ARC,    16);
    check("FIN user6_d8  msg12",  user6_d8,  EXP_P2_USER6,   6);

    // ---- DATA_WIDTH = 32, big-endian beats (CRC-32) -------------------------
    do_reset();
    for (int i = 0; i < N_BEAT_CRC32_D32_BE; i++) send32(BEAT_CRC32_D32_BE[i]);
    #1;
    check("FIN crc32_d32_be",  crc32_d32_be,  EXP_CRC32_D32_BE, 32);

    // ---- DATA_WIDTH = 32, big-endian beats (CRC-32/MPEG-2) -------------------
    do_reset();
    for (int i = 0; i < N_BEAT_MPEG2_D32_BE; i++) send32(BEAT_MPEG2_D32_BE[i]);
    #1;
    check("FIN mpeg2_d32_be",  mpeg2_d32_be,  EXP_MPEG2_D32_BE, 32);

    // ---- DATA_WIDTH = 32, little-endian beats -------------------------------
    do_reset();
    for (int i = 0; i < N_BEAT_CRC32_D32_LE; i++) send32le(BEAT_CRC32_D32_LE[i]);
    #1;
    check("FIN crc32_d32_le",  crc32_d32_le,  EXP_CRC32_D32_LE, 32);

    // ---- DATA_WIDTH = 12 (tail path) ----------------------------------------
    do_reset();
    for (int i = 0; i < N_BEAT_MPEG2_D12_BE; i++) send12(BEAT_MPEG2_D12_BE[i]);
    #1;
    check("FIN mpeg2_d12_be",  mpeg2_d12_be,  EXP_MPEG2_D12_BE, 32);

    // ---- DATA_WIDTH = 16, little-endian beats --------------------------------
    do_reset();
    for (int i = 0; i < N_BEAT_MODBUS_D16_LE; i++) send16le(BEAT_MODBUS_D16_LE[i]);
    #1;
    check("FIN modbus_d16_le", modbus_d16_le, EXP_MODBUS_D16_LE, 16);

    // ---- DATA_WIDTH = 24 -----------------------------------------------------
    do_reset();
    for (int i = 0; i < N_BEAT_XMODEM_D24_BE; i++) send24(BEAT_XMODEM_D24_BE[i]);
    #1;
    check("FIN xmodem_d24_be", xmodem_d24_be, EXP_XMODEM_D24_BE, 16);

    // ---- module defaults, DATA_WIDTH = 16 (tail + REFIN) ---------------------
    do_reset();
    for (int i = 0; i < N_BEAT_USER6_D16_BE; i++) send16(BEAT_USER6_D16_BE[i]);
    #1;
    check("FIN user6_d16_be",  user6_d16_be,  EXP_USER6_D16_BE, 6);

    // ---- module defaults, DATA_WIDTH = 6 -------------------------------------
    do_reset();
    for (int i = 0; i < N_BEAT_USER6_D6_BE; i++) send6(BEAT_USER6_D6_BE[i]);
    #1;
    check("FIN user6_d6_be",   user6_d6_be,   EXP_USER6_D6_BE, 6);

    // ---- nibble beats ---------------------------------------------------------
    do_reset();
    for (int i = 0; i < N_BEAT_CCITTF_D4_BE; i++) send4(BEAT_CCITTF_D4_BE[i]);
    #1;
    check("FIN ccittf_d4_be",  ccittf_d4_be,  EXP_CCITTF_D4_BE, 16);

    // ---- 3-bit beats ----------------------------------------------------------
    do_reset();
    for (int i = 0; i < N_BEAT_SMBUS_D3_BE; i++) send3(BEAT_SMBUS_D3_BE[i]);
    #1;
    check("FIN smbus_d3_be",   smbus_d3_be,   EXP_SMBUS_D3_BE, 8);

    // ---- module defaults, 3-bit beats (sub-byte lane reflection) ---------------
    do_reset();
    for (int i = 0; i < N_BEAT_USER6_D3_BE; i++) send3u(BEAT_USER6_D3_BE[i]);
    #1;
    check("FIN user6_d3_be",   user6_d3_be,   EXP_USER6_D3_BE, 6);

    // ---- bit-serial beats, pre-reflected stream (REFIN=0) ---------------------
    do_reset();
    for (int i = 0; i < N_BEAT_CRC32_D1_REF0; i++) send1a(BEAT_CRC32_D1_REF0[i]);
    #1;
    check("FIN crc32_d1_ref0", crc32_d1_ref0, EXP_CRC32_D1_REF0, 32);

    // ---- bit-serial beats, raw stream (REFIN=1) --------------------------------
    do_reset();
    for (int i = 0; i < N_BEAT_CRC32_D1_REF1; i++) send1b(BEAT_CRC32_D1_REF1[i]);
    #1;
    check("FIN crc32_d1_ref1", crc32_d1_ref1, EXP_CRC32_D1_REF1, 32);

    // ---- summary ----------------------------------------------------------------
    if (errors == 0) begin
      $display("");
      $display("==========================================================");
      $display("[TB] ALL %0d CHECKS PASSED", checks);
      $display("==========================================================");
    end else begin
      $display("");
      $display("==========================================================");
      $display("[TB] %0d of %0d CHECKS FAILED", errors, checks);
      $display("==========================================================");
    end
    $finish;
  end

endmodule
